import { comfy } from '/comfy/api/v1.js';

comfy.defs.extend('FastPreview', (b) => {
  // Per-node preview state. Handles hold no arbitrary properties, and the
  // entry is dropped in onRemoved.
  const previews = new Map();

  b.onCreated((node) => {
    node.setSize({ width: 550, height: 550 });

    const state = { img: null };
    state.canvas = node.widgets.canvas({
      name: 'preview',
      draw(ctx, [w, h]) {
        const img = state.img;
        if (!img) return;
        const scale = Math.min(w / img.width, h / img.height);
        const dw = img.width * scale, dh = img.height * scale;
        ctx.drawImage(img, (w - dw) / 2, (h - dh) / 2, dw, dh);
      },
    });
    previews.set(node.id, state);
  });

  // onPreview answers "is this frame mine?" for us — the `executing` global,
  // the displayNodeId test and the supports_preview_metadata probe all go away.
  b.onPreview((node, frame) => {
    const state = previews.get(node.id);
    if (!state) return;
    const img = new Image();
    img.onload = () => { state.img = img; state.canvas.redraw(); };
    img.src = URL.createObjectURL(frame.blob);
  });

  b.onRemoved((node) => {
    previews.delete(node.id);
  });
});

import { comfy } from '/comfy/api/v1.js';
const { api } = window.comfyAPI.api;

comfy.defs.extend("PlaySoundKJ", (b) => {
    // Per-node playback state: handles carry no arbitrary properties, so the
    // former this._kj* fields live here, keyed by node.id.
    const states = new Map();
    const stateFor = (node) => {
        if (!states.has(node.id)) states.set(node.id, {});
        return states.get(node.id);
    };
    // Was inline in onExecuted; shared now that removal has to clean up too.
    const stopPlayback = (state) => {
        if (state.statusListener) {
            api.removeEventListener("status", state.statusListener);
            state.statusListener = null;
        }
        clearTimeout(state.queueDebounce);
        state.pendingAudio = null;

        if (state.playingAudio) {
            state.playingAudio.pause();
            state.playingAudio = null;
        }
        if (state.playTimer != null) {
            clearTimeout(state.playTimer);
            state.playTimer = null;
        }
    };

    // "status" is the queue-status event, not a node preview, so it stays on
    // the api client.
    b.onExecuted((node, result) => {
        const audios = result.raw?.audio;
        if (!audios?.length) return;

        const state = stateFor(node);
        const modeWidget = node.widgets.get("mode");
        const volumeWidget = node.widgets.get("volume");
        const durationWidget = node.widgets.get("duration");
        const mode = modeWidget?.getValue() ?? "always";
        const volume = volumeWidget?.getValue() ?? 0.5;
        const duration = durationWidget?.getValue() ?? 0;

        // on_change: skip if audio content hasn't changed
        if (mode === "on_change") {
            const audioHash = result.raw?.audio_hash?.[0];
            if (audioHash != null && state.lastAudioHash === audioHash) return;
            state.lastAudioHash = audioHash;
        }

        // Clean up previous state
        stopPlayback(state);

        const startPlayback = () => {
            const { filename, subfolder, type } = audios[0];
            const params = new URLSearchParams({
                filename: filename ?? "",
                subfolder: subfolder ?? "",
                type: type ?? "temp",
            });
            const url = api.apiURL(`/view?${params.toString()}`);
            const audio = new Audio(url);
            audio.volume = Math.max(0, Math.min(1, volume));
            audio.play().catch(() => {});
            state.playingAudio = audio;
            if (duration > 0) {
                state.playTimer = setTimeout(() => {
                    audio.pause();
                    state.playingAudio = null;
                    state.playTimer = null;
                }, duration * 1000);
            }
        };

        if (mode === "on_empty_queue") {
            state.pendingAudio = startPlayback;
            state.statusListener = ({ detail }) => {
                const remaining = detail?.exec_info?.queue_remaining ?? 0;
                if (remaining === 0) {
                    // Debounce: confirm queue is truly empty
                    // (status can briefly show 0 between dispatches)
                    clearTimeout(state.queueDebounce);
                    state.queueDebounce = setTimeout(() => {
                        if (state.pendingAudio) {
                            state.pendingAudio();
                            state.pendingAudio = null;
                        }
                        api.removeEventListener("status", state.statusListener);
                        state.statusListener = null;
                    }, 1000);
                } else {
                    clearTimeout(state.queueDebounce);
                }
            };
            api.addEventListener("status", state.statusListener);
        } else {
            startPlayback();
        }
    });

    // The old code hung its state off the node, so deleting one mid-playback
    // left the audio running and the "status" listener subscribed forever.
    b.onRemoved((node) => {
        const state = states.get(node.id);
        if (state) stopPlayback(state);
        states.delete(node.id);
    });
});

const { app } = window.comfyAPI.app;

// ─── General-purpose helpers shared across KJNodes JS ───

export function makeUUID() {
  let dt = new Date().getTime()
  const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = ((dt + Math.random() * 16) % 16) | 0
    dt = Math.floor(dt / 16)
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16)
  })
  return uuid
}

export function chainCallback(object, property, callback) {
  if (object == undefined) {
    console.error("Tried to add callback to non-existant object")
    return;
  }
  if (property in object) {
    const callback_orig = object[property]
    object[property] = function () {
      const r = callback_orig.apply(this, arguments);
      callback.apply(this, arguments);
      return r
    };
  } else {
    object[property] = callback;
  }
}

// `node` is a NodeHandle. Hiding is a real property now, so the origType /
// origComputeSize / origSerializeValue bookkeeping — nothing ever read it
// back — and the [0, -4] size hack go away with it.
export function hideWidgetForGood(node, widget) {
  const handle = node.widgets.get(widget.name)
  if (!handle) return console.warn(`hideWidgetForGood: no widget "${widget.name}"`)
  handle.setHidden(true)
  if (widget.linkedWidgets) {
    for (const w of widget.linkedWidgets) {
      hideWidgetForGood(node, w)
    }
  }
}

// ─── Graph coordinate helpers ───

export function clientToCanvas(lgCanvas, clientX, clientY) {
  const rect = lgCanvas.canvas.getBoundingClientRect();
  return [
    (clientX - rect.left) / lgCanvas.ds.scale - lgCanvas.ds.offset[0],
    (clientY - rect.top) / lgCanvas.ds.scale - lgCanvas.ds.offset[1],
  ];
}

export function getNodeAtPoint(graph, cx, cy) {
  for (let i = graph._nodes.length - 1; i >= 0; i--) {
    if (graph._nodes[i].isPointInside(cx, cy)) return graph._nodes[i];
  }
  return null;
}

export function typesCompatible(a, b) {
  if (a === "*" || b === "*") return true;
  if (a === b) return true;
  if (typeof a !== "string" || typeof b !== "string") return false;
  if (a.toUpperCase() === b.toUpperCase()) return true;
  // ComfyUI accepts union types like "STRING,INT" — match if any token overlaps
  if (a.includes(",") || b.includes(",")) {
    const aTokens = a.toUpperCase().split(",").map(s => s.trim()).filter(Boolean);
    const bTokens = b.toUpperCase().split(",").map(s => s.trim()).filter(Boolean);
    if (aTokens.includes("*") || bTokens.includes("*")) return true;
    return aTokens.some(t => bTokens.includes(t));
  }
  return false;
}

// ─── Slot position helper ───
// Uses modern API (DOM-registered positions in Vue mode) with legacy fallback
export function getSlotPos(node, isInput, slotIdx) {
  if (isInput && node.getInputPos) return node.getInputPos(slotIdx);
  if (!isInput && node.getOutputPos) return node.getOutputPos(slotIdx);
  const out = [0, 0];
  node.getConnectionPos(isInput, slotIdx, out);
  return out;
}

// ─── Middle-click pan passthrough for DOM widgets ───
// Allows panning the LiteGraph canvas via middle-click drag on any DOM element
export function addMiddleClickPan(element) {
  const onMouseDown = (e) => {
    if (e.button !== 1) return;
    e.preventDefault();
    const ds = app.canvas?.ds;
    if (!ds) return;
    const startX = e.clientX, startY = e.clientY;
    const startOffsetX = ds.offset[0], startOffsetY = ds.offset[1];
    const onMove = (me) => {
      const scale = ds.scale || 1;   // offset is graph-space; LiteGraph pans by (screen delta / scale)
      ds.offset[0] = startOffsetX + (me.clientX - startX) / scale;
      ds.offset[1] = startOffsetY + (me.clientY - startY) / scale;
      app.canvas.setDirty(true, true);
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  };
  element.addEventListener('mousedown', onMouseDown);
  return () => element.removeEventListener('mousedown', onMouseDown);
}

// ─── Resolve preview image/video from a connected source node ───
// Walks the graph link to find what's connected to node.inputs[inputSlot]
// and returns { url, isVideo, videoEl } or null
export function resolveSourcePreview(node, inputSlot) {
  if (!node.graph) return null;
  const input = node.inputs?.[inputSlot];
  if (!input || input.link == null) return null;
  const link = node.graph.links?.get(input.link);
  if (!link) return null;
  const srcNode = node.graph.getNodeById(link.origin_id);
  if (!srcNode) return null;

  // Check for VHS-style video preview widget
  const vpWidget = srcNode.widgets?.find((w) => w.name === "videopreview");
  if (vpWidget?.videoEl?.src) {
    return { isVideo: true, videoEl: vpWidget.videoEl };
  }

  // Look for a LoadImage "image" widget or LoadVideo "video" widget
  const w = srcNode.widgets?.find((w) => w.name === "image" || w.name === "video");
  if (w?.value) {
    let subfolder = "", fname = w.value;
    const lastSlash = fname.lastIndexOf("/");
    if (lastSlash >= 0) { subfolder = fname.substring(0, lastSlash); fname = fname.substring(lastSlash + 1); }
    const isVideo = w.name === "video";
    const url = `/view?filename=${encodeURIComponent(fname)}&type=input&subfolder=${encodeURIComponent(subfolder)}`;
    return { url, isVideo };
  }

  // Fallback: check node.imgs (set after execution)
  if (srcNode.imgs?.length > 0 && srcNode.imgs[0].src) {
    return { url: srcNode.imgs[0].src, isVideo: false };
  }
  return null;
}

// ─── Source input watcher ───
// Watches a named IMAGE input for connection changes and source widget changes.
// Calls onChange(sources) when connections change or the source node's image/video widget changes.
// sources: array of { url, isVideo, videoEl } per connected IMAGE input matching inputName (or all if inputName is null).
// Returns a cleanup function.
export function watchImageInputs(node, inputName, onChange) {
  let watchedWidgets = [];

  function unwatchWidgets() {
    for (const { widget, origCb } of watchedWidgets) widget.callback = origCb;
    watchedWidgets = [];
  }

  function resolve() {
    if (!node.inputs) return [];
    const slots = inputName
      ? node.inputs.map((inp, i) => inp.name === inputName ? i : -1).filter(i => i >= 0)
      : node.inputs.map((inp, i) => inp.type === "IMAGE" ? i : -1).filter(i => i >= 0);
    return slots.map(i => resolveSourcePreview(node, i)).filter(s => s !== null);
  }

  function watch() {
    unwatchWidgets();
    if (!node.inputs || !node.graph) return;
    const slots = inputName
      ? node.inputs.map((inp, i) => inp.name === inputName ? i : -1).filter(i => i >= 0)
      : node.inputs.map((inp, i) => inp.type === "IMAGE" ? i : -1).filter(i => i >= 0);
    for (const slotIdx of slots) {
      const input = node.inputs[slotIdx];
      if (!input || input.link == null) continue;
      const link = node.graph.links?.get(input.link);
      if (!link) continue;
      const srcNode = node.graph.getNodeById(link.origin_id);
      if (!srcNode) continue;
      const w = srcNode.widgets?.find(w => w.name === "image" || w.name === "video");
      if (!w) continue;
      const origCb = w.callback;
      w.callback = function (...args) {
        if (origCb) origCb.apply(this, args);
        setTimeout(() => onChange(resolve()), 100);
      };
      watchedWidgets.push({ widget: w, origCb });
    }
  }

  chainCallback(node, "onConnectionsChange", function (type) {
    // Only react to input connection changes, not output
    if (type != null && type !== 1) return;
    setTimeout(() => {
      watch();
      onChange(resolve());
    }, 100);
  });

  chainCallback(node, "onRemoved", unwatchWidgets);

  return unwatchWidgets;
}

// ─── Video frame capture ───
// Draws the current frame of a video element to a fresh canvas at native resolution.
// If the video isn't decoded yet (readyState < 2), waits once for "loadeddata" before capturing.
// Calls callback(canvas) with the resulting canvas. Caller decides whether to use it directly
// (drawImage accepts canvas) or convert via toDataURL.
export function captureVideoFrame(videoEl, callback) {
  const capture = () => {
    if (!videoEl.videoWidth || !videoEl.videoHeight) return;
    const c = document.createElement("canvas");
    c.width = videoEl.videoWidth;
    c.height = videoEl.videoHeight;
    c.getContext("2d").drawImage(videoEl, 0, 0);
    callback(c);
  };
  if (videoEl.readyState >= 2) {
    capture();
  } else {
    const onReady = () => { videoEl.removeEventListener("loadeddata", onReady); capture(); };
    videoEl.addEventListener("loadeddata", onReady);
  }
}

// ─── Bounding box hit test ───
// Tests whether (mx, my) hits a corner handle or the interior of a rect defined by (x1, y1)–(x2, y2).
// Returns "resize-tl", "resize-tr", "resize-bl", "resize-br", "resize-t", "resize-b", "resize-l", "resize-r", "move", or null.
export function rectHitTest(mx, my, x1, y1, x2, y2, radius) {
  const hit = (cx, cy) => Math.abs(mx - cx) < radius && Math.abs(my - cy) < radius;
  // Corners first (higher priority)
  if (hit(x1, y1)) return "resize-tl";
  if (hit(x2, y1)) return "resize-tr";
  if (hit(x1, y2)) return "resize-bl";
  if (hit(x2, y2)) return "resize-br";
  // Edges
  if (mx >= x1 && mx <= x2 && Math.abs(my - y1) < radius) return "resize-t";
  if (mx >= x1 && mx <= x2 && Math.abs(my - y2) < radius) return "resize-b";
  if (my >= y1 && my <= y2 && Math.abs(mx - x1) < radius) return "resize-l";
  if (my >= y1 && my <= y2 && Math.abs(mx - x2) < radius) return "resize-r";
  // Interior
  if (mx >= x1 && mx <= x2 && my >= y1 && my <= y2) return "move";
  return null;
}

// Returns the appropriate CSS cursor for a bbox hit mode string.
export function cursorForBboxMode(mode) {
  if (mode === "move") return "move";
  if (mode === "resize-tl" || mode === "resize-br") return "nwse-resize";
  if (mode === "resize-tr" || mode === "resize-bl") return "nesw-resize";
  if (mode === "resize-t" || mode === "resize-b") return "ns-resize";
  if (mode === "resize-l" || mode === "resize-r") return "ew-resize";
  return null;
}

// ─── Wheel zoom passthrough for DOM widgets ───
// Re-dispatches wheel events to the LiteGraph canvas for zoom
export function addWheelPassthrough(element) {
  element.addEventListener("wheel", (e) => {
    const gc = document.getElementById("graph-canvas");
    if (gc) {
      gc.dispatchEvent(new WheelEvent(e.type, e));
      e.preventDefault();
    }
  }, { passive: false });
}
